// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MyContract} from "../src/MyContract.sol";

contract InvMutTest is Test {
    MyContract c;

    function setUp() public {
        c = new MyContract();
        vm.deal(address(c), 100 ether);
    }

    function testFuzz_property(uint256 amount, address receiver) public {
        vm.assume(receiver != owner());
        vm.assume(receiver.code.length == 0);
        amount = bound(amount, 1, address(c).balance);

        uint256 before = receiver.balance;
        vm.prank(owner());
        c.sendTo(receiver, amount);

        assertEq(receiver.balance, before + amount);
    }

    function owner() internal view returns (address) {
        return address(this);
    }
}
